34	func NewCloudClient(cfg CloudConfig) *CloudClient {
35		baseURL := cfg.BaseURL
36		if baseURL == "" {
37			baseURL = api.BaseURL()
38		}
39	
40		httpClient := cfg.HTTP
41		if httpClient == nil {
42			timeout := cfg.Timeout
43			if timeout <= 0 {
44				timeout = defaultCloudHTTPTimeout
45			}
46			httpClient = &http.Client{Timeout: timeout}
47		} else if cfg.Timeout > 0 && httpClient.Timeout == 0 {
48			httpClient.Timeout = cfg.Timeout
49		}
50	
51		return &CloudClient{
52			baseURL: strings.TrimRight(baseURL, "/"),
53			token:   cfg.Token,
54			http:    httpClient,
55		}
