126	func (b *APIBranches) UnmarshalJSON(data []byte) error {
127		if bytes.Equal(data, []byte("null")) {
128			*b = APIBranches{}
129			return nil
130		}
131	
132		var values []string
133		if err := json.Unmarshal(data, &values); err == nil {
134			*b = APIBranches{Values: values}
135			return nil
136		}
137	
138		var sentinel string
139		if err := json.Unmarshal(data, &sentinel); err != nil {
140			return fmt.Errorf("decode branches: %w", err)
141		}
142		if sentinel != "all" {
143			return fmt.Errorf("decode branches: unexpected sentinel %q", sentinel)
144		}
145		*b = APIBranches{All: true}
146		return nil
147	}
