149	func (c *CloudClient) CreateDispatch(ctx context.Context, reqBody CreateDispatchRequest) (*CreateDispatchResponse, error) {
150		var out CreateDispatchResponse
151		if err := c.doJSON(ctx, http.MethodPost, "/api/v1/dispatches/generate", reqBody, &out); err != nil {
152			return nil, err
153		}
154		return &out, nil
155	}
