157	func (c *CloudClient) doJSON(ctx context.Context, method, path string, reqBody, out any) error {
158		var body io.Reader
159		if reqBody != nil {
160			data, err := json.Marshal(reqBody)
161			if err != nil {
162				return fmt.Errorf("marshal request body: %w", err)
163			}
164			body = bytes.NewReader(data)
165		}
166	
167		req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, body)
168		if err != nil {
169			return fmt.Errorf("create request: %w", err)
170		}
171		req.Header.Set("Accept", "application/json")
172		if reqBody != nil {
173			req.Header.Set("Content-Type", "application/json")
174		}
175		if c.token != "" {
176			req.Header.Set("Authorization", "Bearer "+c.token)
177		}
178	
179		resp, err := c.http.Do(req)
180		if err != nil {
181			return fmt.Errorf("%s %s: %w", method, path, err)
182		}
183		defer resp.Body.Close()
184	
185		if resp.StatusCode == http.StatusUnauthorized {
186			return errors.New("dispatch requires login — run `entire login`")
187		}
188		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
189			body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20)) //nolint:errcheck // best-effort body read for error message
190			trimmed := strings.TrimSpace(string(body))
191			logging.Warn(ctx, "dispatch request failed", "method", method, "path", path, "status_code", resp.StatusCode)
192			if trimmed == "" {
193				return fmt.Errorf("dispatch service returned status %d", resp.StatusCode)
194			}
195			return fmt.Errorf("dispatch service returned status %d: %s", resp.StatusCode, strconv.Quote(trimmed))
196		}
197		if out == nil {
198			return nil
199		}
200		if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
201			return fmt.Errorf("decode response: %w", err)
202		}
203		return nil
204	}
