15	// requireSecureDispatchURL is the secure-base-URL guard used before the cloud
16	// client sends a bearer token. Tests swap it to allow httptest.NewServer
17	// (http://127.0.0.1:...) endpoints; production always routes through
18	// api.RequireSecureURL and rejects plain HTTP.
19	var requireSecureDispatchURL = api.RequireSecureURL
