21	func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
22		token, err := lookupCurrentToken()
23		if err != nil {
24			return nil, fmt.Errorf("reading credentials: %w", err)
25		}
26		if token == "" {
27			return nil, errors.New("dispatch requires login — run `entire login`")
28		}
29	
30		baseURL := api.BaseURL()
31		if !opts.InsecureHTTPAuth {
32			if err := requireSecureDispatchURL(baseURL); err != nil {
33				return nil, fmt.Errorf("dispatch base URL: %w", err)
34			}
35		}
36	
37		now := nowUTC()
38		sinceInput := strings.TrimSpace(opts.Since)
39		if sinceInput == "" {
40			sinceInput = "7d"
41		}
42		since, err := ParseSinceAtNow(sinceInput, now)
43		if err != nil {
44			return nil, err
45		}
46		until, err := ParseUntilAtNow(opts.Until, now)
47		if err != nil {
48			return nil, err
49		}
50		normalizedSince, normalizedUntil := NormalizeWindow(since, until)
51		if !normalizedSince.Before(normalizedUntil) {
52			return nil, errors.New("--since must be before --until")
53		}
54	
55		repos := append([]string(nil), opts.RepoPaths...)
56		if len(repos) == 0 {
57			repoRoot, err := paths.WorktreeRoot(ctx)
58			if err != nil {
59				return nil, fmt.Errorf("not in a git repository: %w", err)
60			}
61			repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
62			if err != nil {
63				return nil, fmt.Errorf("open repository: %w", err)
64			}
65			repoFullName, err := resolveRepoFullName(ctx, repo)
66			if err != nil {
67				return nil, err
68			}
69			repos = []string{repoFullName}
70		}
71	
72		cloud := NewCloudClient(CloudConfig{BaseURL: baseURL, Token: token})
73		reqBody := CreateDispatchRequest{
74			Repos:    repos,
75			Since:    normalizedSince.Format(time.RFC3339),
76			Until:    normalizedUntil.Format(time.RFC3339),
77			Generate: true,
78			Voice:    resolvedDispatchVoicePreference(opts.Voice),
79		}
80		response, err := cloud.CreateDispatch(ctx, reqBody)
81		if err != nil {
82			return nil, err
83		}
84	
85		dispatch := apiToDispatch(response)
86		if strings.TrimSpace(dispatch.GeneratedText) == "" {
87			return nil, errDispatchMissingMarkdown
88		}
89		return dispatch, nil
90	}
