92	func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
93		if response == nil {
94			return &Dispatch{}
95		}
96	
97		repos := make([]RepoGroup, 0, len(response.Repos))
98		for _, repo := range response.Repos {
99			sections := make([]Section, 0, len(repo.Sections))
100			for _, section := range repo.Sections {
101				bullets := make([]Bullet, 0, len(section.Bullets))
102				for _, bullet := range section.Bullets {
103					bullets = append(bullets, Bullet{
104						CheckpointID: bullet.CheckpointID,
105						Text:         bullet.Text,
106						Source:       bullet.Source,
107						Branch:       bullet.Branch,
108						CreatedAt:    parseAPITime(bullet.CreatedAt),
109						Labels:       append([]string(nil), bullet.Labels...),
110					})
111				}
112				sections = append(sections, Section{
113					Label:   section.Label,
114					Bullets: bullets,
115				})
116			}
117			repos = append(repos, RepoGroup{
118				FullName: repo.FullName,
119				Sections: sections,
120			})
121		}
122	
123		generatedText := strings.TrimSpace(response.GeneratedMarkdown)
124		if generatedText == "" {
125			generatedText = strings.TrimSpace(response.GeneratedText)
126		}
127	
128		return &Dispatch{
129			Window: Window{
130				NormalizedSince:   parseAPITime(response.Window.NormalizedSince),
131				NormalizedUntil:   parseAPITime(response.Window.NormalizedUntil),
132				FirstCheckpointAt: parseAPITime(response.Window.FirstCheckpointCreatedAt),
133				LastCheckpointAt:  parseAPITime(response.Window.LastCheckpointCreatedAt),
134			},
135			CoveredRepos:  append([]string(nil), response.CoveredRepos...),
136			Repos:         repos,
137			GeneratedText: generatedText,
138		}
139	}
140	
141	func parseAPITime(value string) time.Time {
142		if value == "" {
143			return time.Time{}
144		}
145		parsed, err := time.Parse(time.RFC3339, value)
146		if err != nil {
147			return time.Time{}
148		}
149		return parsed
150	}
