302		remote, err := repo.Remote("origin")
303		if err != nil {
304			logging.Warn(ctx, "dispatch repo resolution failed", "step", "origin_remote", "error", err)
305			return "", fmt.Errorf("dispatch currently supports GitHub repositories with an origin remote: %w", err)
306		}
