353	// newLazyOptions returns a func that runs loader once (under sync.Once) and
354	// returns the cached result on subsequent calls. Safe for concurrent use.
355	func newLazyOptions(loader func() []huh.Option[string]) func() []huh.Option[string] {
356		var (
357			once    sync.Once
358			options []huh.Option[string]
359		)
360		return func() []huh.Option[string] {
361			once.Do(func() {
362				options = loader()
363			})
364			return options
365		}
366	}
