402	func discoverLocalRepoRoots(ctx context.Context, currentRepo string) []string {
403		rootSet := map[string]struct{}{currentRepo: {}}
404		parent := filepath.Dir(currentRepo)
405	
406		entries, err := os.ReadDir(parent)
407		if err == nil {
408			candidates := make([]string, 0, len(entries))
409			for _, entry := range entries {
410				if !entry.IsDir() {
411					continue
412				}
413				candidate := filepath.Join(parent, entry.Name())
414				if _, statErr := os.Stat(filepath.Join(candidate, ".git")); statErr != nil {
415					continue
416				}
417				candidates = append(candidates, candidate)
418			}
419	
420			resolved := make([]string, len(candidates))
421			sem := make(chan struct{}, dispatchWizardRepoDiscoveryConcurrencyLimit)
422			var wg sync.WaitGroup
423			wg.Add(len(candidates))
424			for i, candidate := range candidates {
425				sem <- struct{}{}
426				go func(i int, candidate string) {
427					defer wg.Done()
428					defer func() { <-sem }()
429					if repoRoot, resolveErr := resolveDispatchWizardTopLevel(ctx, candidate); resolveErr == nil {
430						resolved[i] = repoRoot
431					}
432				}(i, candidate)
433			}
434			wg.Wait()
435			for _, repoRoot := range resolved {
436				if repoRoot != "" {
437					rootSet[repoRoot] = struct{}{}
438				}
439			}
440		}
441	
442		repoRoots := make([]string, 0, len(rootSet))
443		for repoRoot := range rootSet {
444			repoRoots = append(repoRoots, repoRoot)
445		}
446		sort.Slice(repoRoots, func(i, j int) bool {
447			if repoRoots[i] == currentRepo {
448				return true
449			}
450			if repoRoots[j] == currentRepo {
451				return false
452			}
453			return filepath.Base(repoRoots[i]) < filepath.Base(repoRoots[j])
454		})
455		return repoRoots
456	}
457	
458	func discoverLocalRepoSlugs(ctx context.Context, currentRepo string) []string {
459		repoRoots := discoverLocalRepoRoots(ctx, currentRepo)
460		repoSlugs := make([]string, 0, len(repoRoots))
461		seenRepoSlugs := make(map[string]struct{}, len(repoRoots))
462		for _, repoRoot := range repoRoots {
463			repoSlug := discoverRepoSlug(repoRoot)
464			if repoSlug == "" {
465				continue
466			}
467			if _, ok := seenRepoSlugs[repoSlug]; ok {
468				continue
469			}
470			seenRepoSlugs[repoSlug] = struct{}{}
471			repoSlugs = append(repoSlugs, repoSlug)
472		}
473		return repoSlugs
474	}
475	
476	func resolveGitTopLevel(ctx context.Context, path string) (string, error) {
477		cmd := exec.CommandContext(ctx, "git", "-C", path, "rev-parse", "--show-toplevel")
478		output, err := cmd.Output()
479		if err != nil {
480			return "", fmt.Errorf("git rev-parse --show-toplevel: %w", err)
481		}
482		return strings.TrimSpace(string(output)), nil
483	}
