485	func discoverAuthenticatedDispatchWizardRepos(ctx context.Context) ([]string, error) {
486		cmd := exec.CommandContext(
487			ctx,
488			"gh",
489			"api",
490			"--paginate",
491			"user/repos?per_page=100&affiliation=owner,collaborator,organization_member&sort=full_name",
492			"--jq",
493			".[].full_name",
494		)
495		output, err := cmd.Output()
496		if err != nil {
497			return nil, fmt.Errorf("gh api user/repos: %w", err)
498		}
499	
500		repos := make([]string, 0)
501		seen := make(map[string]struct{})
502		for _, line := range strings.Split(string(output), "\n") {
503			line = strings.TrimSpace(line)
504			if line == "" {
505				continue
506			}
507			if _, ok := seen[line]; ok {
508				continue
509			}
510			seen[line] = struct{}{}
511			repos = append(repos, line)
512		}
513		sort.Strings(repos)
514		return repos, nil
515	}
516	
517	func discoverRepoSlug(repoRoot string) string {
518		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
519		if err != nil {
520			return ""
521		}
522		remote, err := repo.Remote("origin")
523		if err != nil || len(remote.Config().URLs) == 0 {
524			return ""
525		}
526		owner, repoName, err := searchpkg.ParseGitHubRemote(remote.Config().URLs[0])
527		if err != nil {
528			return ""
529		}
530		return owner + "/" + repoName
531	}
