// discoverAuthenticatedDispatchWizardRepos lists the authenticated user's
// repositories via the Entire API (/api/v1/repositories), dropping any with
// no checkpoints — dispatching them would produce nothing.
// Server-side ordering (recent-first) is preserved.
func discoverAuthenticatedDispatchWizardRepos(ctx context.Context) ([]string, error) {
	client, err := newDispatchWizardAPIClient()
	if err != nil {
		return nil, err
	}

	repos, err := client.ListRepositories(ctx, api.RepositorySortRecent)
	if err != nil {
		logging.Warn(ctx, "dispatch wizard repo list failed", "error", err)
		return nil, err
	}

	slugs := make([]string, 0, len(repos))
	for _, repo := range repos {
		if repo.CheckpointCount <= 0 {
			continue
		}
		slug := strings.TrimSpace(repo.FullName)
		if slug == "" {
			continue
		}
		slugs = append(slugs, slug)
	}
	return slugs, nil
}

